window.__QUIZ_CHUNKS__.A1 = {"A1":{"vocab":[{"id":"q-vocab-a1-0001","level":"A1","skill":"vocab","prompt":"「le prénom」的意思是：","options":["名字（名）","姓氏","职业","国籍"],"answer":"名字（名）","explain":"prénom 是「名」（如 Marie、Paul），姓是 le nom（de famille）；profession 是职业，nationalité 是国籍。","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-a1-0002","level":"A1","skill":"vocab","prompt":"「J'ai vingt ans.」表达「我 20 岁」，法语年龄用什么动词？","options":["avoir","être","faire","aller"],"answer":"avoir","explain":"法语年龄固定用 avoir + 数字 + ans；être 是中国人最常见的错法（je suis vingt ans），faire 和 aller 都不用于年龄。","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-a1-0003","level":"A1","skill":"vocab","prompt":"「l'âge」的意思是：","options":["年龄","身高","地址","名字"],"answer":"年龄","explain":"âge 是年龄；身高是 la taille，地址是 l'adresse，名字是 le nom。","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-a1-0004","level":"A1","skill":"vocab","prompt":"「Comment vous appelez-vous ?」问的是：","options":["姓名","年龄","住址","职业"],"answer":"姓名","explain":"s'appeler 用来问姓名；问年龄是 Quel âge avez-vous ?，问住址是 Où habitez-vous ?，问职业是 Quelle est votre profession ?","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-a1-0005","level":"A1","skill":"vocab","prompt":"「le beau-père」可能指：","options":["岳父或继父","亲哥哥","表弟","教父"],"answer":"岳父或继父","explain":"beau-père 既指岳父/公公，也指继父；亲哥哥是 le frère aîné，表弟是 le cousin，教父是 le parrain。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-a1-0006","level":"A1","skill":"vocab","prompt":"「ma sœur cadette」的意思是：","options":["我的妹妹","我的姐姐","我的表姐","我的嫂子"],"answer":"我的妹妹","explain":"cadet / cadette 指家中年幼的，所以 sœur cadette 是妹妹；姐姐是 sœur aînée，表姐是 cousine，嫂子是 belle-sœur。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-a1-0007","level":"A1","skill":"vocab","prompt":"「les grands-parents」指的是：","options":["祖父母（含外祖父母）","个子很高的父母","教父母","成年子女"],"answer":"祖父母（含外祖父母）","explain":"grands-parents 是祖父母与外祖父母的统称；教父母是 parrain / marraine，成年子女是 enfants adultes。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-a1-0008","level":"A1","skill":"vocab","prompt":"Il est marié et il a deux ___ .","options":["enfants","enfant","enfantés","enfance"],"answer":"enfants","explain":"两个孩子要用复数 enfants；enfant 是单数，enfantés 是动词分词，enfance 是名词「童年」。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-a1-0009","level":"A1","skill":"vocab","prompt":"「avoir mal à la tête」的意思是：","options":["头疼","头发乱","撞到头","头晕"],"answer":"头疼","explain":"avoir mal à + 身体部位表示该部位疼痛；头发乱是 avoir les cheveux en désordre，撞到头是 se cogner la tête，头晕是 avoir la tête qui tourne。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-a1-0010","level":"A1","skill":"vocab","prompt":"在药店语境里，「l'ordonnance」指：","options":["处方","意见","命令","账单"],"answer":"处方","explain":"ordonnance 在医疗语境指处方（也可指法令）；意见是 avis，账单是 addition / note。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-a1-0011","level":"A1","skill":"vocab","prompt":"「Je suis enrhumé.」的意思是：","options":["我感冒了","我发烧了","我受伤了","我过敏了"],"answer":"我感冒了","explain":"enrhumé 来自 s'enrhumer（感冒）；发烧是 avoir de la fièvre，受伤是 être blessé，过敏是 faire une allergie。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-a1-0012","level":"A1","skill":"vocab","prompt":"「prendre un médicament」的意思是：","options":["吃药","拿药方","打针","量体温"],"answer":"吃药","explain":"prendre un médicament 是服药；拿药方是 retirer une ordonnance，打针是 faire une piqûre，量体温是 prendre sa température。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-a1-0013","level":"A1","skill":"vocab","prompt":"「Il est très gentil.」的意思是：","options":["他很和善","他很帅","他很聪明","他很懒"],"answer":"他很和善","explain":"gentil 指为人友善；帅是 beau，聪明是 intelligent，懒是 paresseux。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-a1-0014","level":"A1","skill":"vocab","prompt":"「les cheveux bruns」指：","options":["棕色头发","卷发","光头","长头发"],"answer":"棕色头发","explain":"brun 指深棕色（头发、皮肤）；卷发是 cheveux frisés，光头是 chauve，长发是 cheveux longs。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-a1-0015","level":"A1","skill":"vocab","prompt":"「Elle est très timide.」的意思是：","options":["她很害羞","她很急躁","她很傲慢","她很固执"],"answer":"她很害羞","explain":"timide 是害羞、腼腆；急躁是 nerveux，傲慢是 arrogant，固执是 têtu。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-a1-0016","level":"A1","skill":"vocab","prompt":"「grand et mince」形容一个人：","options":["又高又瘦","又矮又胖","又高又壮","又老又瘦"],"answer":"又高又瘦","explain":"grand 是高的，mince 是瘦的；矮是 petit，胖是 gros，壮实是 costaud，老是 vieux。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-a1-0017","level":"A1","skill":"vocab","prompt":"「un appartement au troisième étage」最准确的意思是：","options":["四楼的一套公寓","三楼的一套公寓","带三个房间的公寓","顶层公寓"],"answer":"四楼的一套公寓","explain":"法语楼层从底层（rez-de-chaussée）之上算起，troisième étage 相当于中文的四楼；房间数是 trois pièces，顶层是 dernier étage。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-a1-0018","level":"A1","skill":"vocab","prompt":"「le loyer」的意思是：","options":["房租","房东","家具","邻居"],"answer":"房租","explain":"loyer 是租金；房东是 propriétaire，家具是 meubles，邻居是 voisin。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-a1-0019","level":"A1","skill":"vocab","prompt":"「déménager」的意思是：","options":["搬家","装修","租房","退租"],"answer":"搬家","explain":"déménager 是搬去别处住；装修是 faire des travaux，租房是 louer，退租是 donner congé。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-a1-0020","level":"A1","skill":"vocab","prompt":"「un immeuble」的意思是：","options":["楼房（整栋建筑）","一套公寓","电梯","车库"],"answer":"楼房（整栋建筑）","explain":"immeuble 指整栋楼房；一套公寓是 un appartement，电梯是 ascenseur，车库是 garage。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-a1-0021","level":"A1","skill":"vocab","prompt":"「le petit déjeuner」的意思是：","options":["早餐","零食","午餐","晚餐"],"answer":"早餐","explain":"petit déjeuner 是早餐，déjeuner 是午餐，dîner 是晚餐；零食是 le goûter。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-a1-0022","level":"A1","skill":"vocab","prompt":"「一瓶水」最合适的法语是：","options":["une bouteille d'eau","une tranche d'eau","un morceau d'eau","une part d'eau"],"answer":"une bouteille d'eau","explain":"量词要与名词类别搭配：bouteille（瓶）用于液体；tranche（片）用于面包、火腿，morceau（块）用于固体食物，part（份）用于蛋糕等。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-a1-0023","level":"A1","skill":"vocab","prompt":"在餐厅里，「la carte」指：","options":["菜单","地图","银行卡","名片"],"answer":"菜单","explain":"餐厅里 la carte 是菜单（点菜 à la carte）；地图、银行卡、名片都另有搭配（carte de France, carte bancaire, carte de visite）。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-a1-0024","level":"A1","skill":"vocab","prompt":"「les fruits de mer」的意思是：","options":["海鲜","海里的水果","干果","蔬菜"],"answer":"海鲜","explain":"fruits de mer 字面是「海里的果实」，实际指海鲜；干果是 fruits secs，蔬菜是 légumes。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-a1-0025","level":"A1","skill":"vocab","prompt":"「les soldes」的意思是：","options":["打折季","收银台","购物袋","小费"],"answer":"打折季","explain":"soldes 指商场的打折促销季；收银台是 caisse，购物袋是 sac，小费是 pourboire。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-a1-0026","level":"A1","skill":"vocab","prompt":"「un reçu」的意思是：","options":["收据","发票","找零","优惠券"],"answer":"收据","explain":"reçu 是付款后拿到的小票、收据；发票是 facture，找零是 monnaie，优惠券是 bon de réduction。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-a1-0027","level":"A1","skill":"vocab","prompt":"「C'est trop cher !」的意思是：","options":["太贵了","太大了","太旧了","太少了"],"answer":"太贵了","explain":"cher 指价格贵；大是 grand，旧是 vieux，少是 peu。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-a1-0028","level":"A1","skill":"vocab","prompt":"J'ai payé ___ carte bancaire.","options":["par","avec","en","à"],"answer":"par","explain":"支付方式用 par + 无冠词名词：payer par carte bancaire（现金是 payer en espèces）；avec 后一般要加冠词（avec une carte），en 用于 en espèces / en chèque，à 不搭配。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-a1-0029","level":"A1","skill":"vocab","prompt":"「une chemise」的意思是：","options":["男式衬衫","女式裙子","大衣","围巾"],"answer":"男式衬衫","explain":"chemise 指（男式）衬衫，女式衬衣式样叫 chemisier；裙子是 jupe，大衣是 manteau，围巾是 écharpe。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-a1-0030","level":"A1","skill":"vocab","prompt":"Je mets mes ___ avant de sortir.（手套）","options":["gants","chaussettes","chaussures","lunettes"],"answer":"gants","explain":"gants 是手套；chaussettes 是袜子，chaussures 是鞋子，lunettes 是眼镜。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-a1-0031","level":"A1","skill":"vocab","prompt":"「les vêtements」的意思是：","options":["衣服（总称）","鞋子","首饰","行李"],"answer":"衣服（总称）","explain":"vêtements 是衣服的总称；鞋子是 chaussures，首饰是 bijoux，行李是 bagages。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-a1-0032","level":"A1","skill":"vocab","prompt":"「en promotion」的意思是：","options":["促销的","全新的","二手的","定做的"],"answer":"促销的","explain":"en promotion 表促销、降价；全新是 neuf，二手是 d'occasion，定做是 sur mesure。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-a1-0033","level":"A1","skill":"vocab","prompt":"「prendre le métro」的意思是：","options":["坐地铁","开地铁","修地铁","等地铁"],"answer":"坐地铁","explain":"prendre + 交通工具表示乘坐；驾驶是 conduire，修理是 réparer，等待是 attendre。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-a1-0034","level":"A1","skill":"vocab","prompt":"「la gare」指：","options":["火车站","地铁站","公交站","机场"],"answer":"火车站","explain":"gare 指火车站（如 gare de Lyon）；地铁站是 station de métro，公交站是 arrêt de bus，机场是 aéroport。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-a1-0035","level":"A1","skill":"vocab","prompt":"「un carrefour」的意思是：","options":["十字路口","高速公路","环岛","人行道"],"answer":"十字路口","explain":"carrefour 是十字路口；高速公路是 autoroute，环岛是 rond-point，人行道是 trottoir。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-a1-0036","level":"A1","skill":"vocab","prompt":"Je descends ___ la prochaine station.","options":["à","dans","sur","en"],"answer":"à","explain":"在某一站下车用介词 à：descendre à la prochaine station；dans 表「在……内部」，sur 表「在……表面」，en 不用于站点。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-a1-0037","level":"A1","skill":"vocab","prompt":"「faire ses valises」的意思是：","options":["收拾行李","买行李箱","寄存行李","给行李称重"],"answer":"收拾行李","explain":"faire ses valises 指收拾行李；买箱子是 acheter une valise，寄存是 mettre à la consigne，称重是 peser。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-a1-0038","level":"A1","skill":"vocab","prompt":"「un aller-retour」的意思是：","options":["往返票","单程票","转机","退票"],"answer":"往返票","explain":"aller-retour 是往返票；单程票是 aller simple，转机是 escale / correspondance，退票是 remboursement。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-a1-0039","level":"A1","skill":"vocab","prompt":"「réserver une chambre d'hôtel」的意思是：","options":["预订酒店房间","打扫酒店房间","退订房间","参观酒店"],"answer":"预订酒店房间","explain":"réserver 是预订；打扫是 nettoyer，退订是 annuler，参观是 visiter。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-a1-0040","level":"A1","skill":"vocab","prompt":"「la douane」的意思是：","options":["海关","行李转盘","登机口","免税店"],"answer":"海关","explain":"douane 是海关（passer la douane 过海关）；行李转盘是 carrousel，登机口是 porte d'embarquement，免税店是 boutique hors taxes。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-a1-0041","level":"A1","skill":"vocab","prompt":"「un entretien d'embauche」的意思是：","options":["求职面试","员工会议","离职谈话","年度考核"],"answer":"求职面试","explain":"entretien d'embauche 是招聘面试；员工会议是 réunion，离职谈话是 entretien de départ，年度考核是 évaluation annuelle。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-a1-0042","level":"A1","skill":"vocab","prompt":"「le salaire」的意思是：","options":["工资","工作时间","同事","假期"],"answer":"工资","explain":"salaire 是工资；工作时间是 horaires，同事是 collègue，假期是 congés。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-a1-0043","level":"A1","skill":"vocab","prompt":"「poser sa candidature」的意思是：","options":["投递求职申请","提出辞职","申请加薪","请病假"],"answer":"投递求职申请","explain":"poser sa candidature 是应聘、投递申请；辞职是 démissionner，申请加薪是 demander une augmentation，请病假是 prendre un congé maladie。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-a1-0044","level":"A1","skill":"vocab","prompt":"「un stage」的意思是：","options":["实习","加班","合同","退休"],"answer":"实习","explain":"stage 是实习，实习生是 stagiaire；加班是 heures supplémentaires，合同是 contrat，退休是 retraite。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-a1-0045","level":"A1","skill":"vocab","prompt":"在学校语境里，「une matière」指：","options":["科目","教材","课桌","分数"],"answer":"科目","explain":"matière 指学科、科目；教材是 manuel，课桌是 table / bureau，分数是 note。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-a1-0046","level":"A1","skill":"vocab","prompt":"「passer un examen」的意思是：","options":["参加考试","通过考试","补考","缺考"],"answer":"参加考试","explain":"passer un examen 是「参加考试」，不是「通过」；通过是 réussir，补考是 repasser，缺考是 sécher l'examen。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-a1-0047","level":"A1","skill":"vocab","prompt":"「la bibliothèque」的意思是：","options":["图书馆","书店","文具店","阅览室管理员"],"answer":"图书馆","explain":"bibliothèque 是图书馆（可借书）；书店是 librairie（假朋友，绝不是 library「图书馆」），文具店是 papeterie。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-a1-0048","level":"A1","skill":"vocab","prompt":"「prendre des notes」的意思是：","options":["记笔记","借笔记","打分","逃课"],"answer":"记笔记","explain":"prendre des notes 是记笔记；借笔记是 emprunter des notes，打分是 noter，逃课是 sécher le cours。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-a1-0049","level":"A1","skill":"vocab","prompt":"在法国，「le 14 juillet」是：","options":["国庆节","圣诞节","复活节","万圣节"],"answer":"国庆节","explain":"7 月 14 日是法国国庆节（la Fête nationale）；圣诞节是 Noël（12 月 25 日），复活节是 Pâques，万圣节是 la Toussaint（11 月 1 日）。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-a1-0050","level":"A1","skill":"vocab","prompt":"「une quinzaine de jours」的意思是：","options":["十五天左右","十五个小时","两个月","五分钟"],"answer":"十五天左右","explain":"quinzaine 来自 quinze，指约半个月；十五小时是 quinze heures，两个月是 deux mois，五分钟是 cinq minutes。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-a1-0051","level":"A1","skill":"vocab","prompt":"「Il est midi et quart.」的意思是：","options":["12 点 15 分","12 点 45 分","1 点 15 分","12 点半"],"answer":"12 点 15 分","explain":"midi 是正午 12 点，et quart 表示一刻钟；12 点半是 et demie，差一刻是 moins le quart，1 点 15 分是 une heure et quart。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-a1-0052","level":"A1","skill":"vocab","prompt":"「un kilo et demi」的意思是：","options":["一公斤半","半公斤","一公斤的四分之一","两公斤"],"answer":"一公斤半","explain":"et demi 表示「再加半个」，un kilo et demi 是一公斤半；半公斤是 un demi-kilo，两公斤是 deux kilos。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"}],"grammar":[{"id":"q-gram-a1-0001","level":"A1","skill":"grammar","prompt":"J'aime ___ musique classique.","options":["la","le","une","les"],"answer":"la","explain":"musique 是阴性单数名词，泛指「音乐」这类事物要用定冠词 la；le 是阳性形式，une 是不定冠词（此处不是「一首/一种」），les 是复数。","source":"语法点 · 定冠词（article défini） · grammar-a1a2.html#art-def"},{"id":"q-gram-a1-0002","level":"A1","skill":"grammar","prompt":"___ soleil brille aujourd'hui.","options":["Le","La","Un","L'"],"answer":"Le","explain":"soleil 是阳性单数名词，而且太阳独一无二，用定冠词 Le；La 是阴性形式，Un 表「一个」不合逻辑，L' 只用于元音或哑音 h 开头。","source":"语法点 · 定冠词（article défini） · grammar-a1a2.html#art-def"},{"id":"q-gram-a1-0003","level":"A1","skill":"grammar","prompt":"___ eau de cette rivière est très froide.","options":["L'","La","Le","Une"],"answer":"L'","explain":"eau 是阴性单数、以元音开头，la 必须省音成 l'；Le 是阳性形式，Une 表「一个/一种」而这里特指这条河的水，La 在元音前必须省音。","source":"语法点 · 定冠词（article défini） · grammar-a1a2.html#art-def"},{"id":"q-gram-a1-0004","level":"A1","skill":"grammar","prompt":"Il y a ___ boulangerie au coin de la rue.","options":["une","un","de la","des"],"answer":"une","explain":"boulangerie 是阴性单数可数名词，第一次提到用不定冠词 une；un 是阳性形式，de la 是部分冠词（只用于不可数），des 是复数。","source":"语法点 · 不定冠词（article indéfini） · grammar-a1a2.html#art-indef"},{"id":"q-gram-a1-0005","level":"A1","skill":"grammar","prompt":"Elle a acheté ___ robe rouge.","options":["une","un","la","les"],"answer":"une","explain":"robe 是阴性单数，首次提到的可数名词用 une；un 与名词性别不符，la 表特指（前文没提过这条裙子），les 是复数。","source":"语法点 · 不定冠词（article indéfini） · grammar-a1a2.html#art-indef"},{"id":"q-gram-a1-0006","level":"A1","skill":"grammar","prompt":"Ce sont ___ étudiants chinois.","options":["des","de","les","un"],"answer":"des","explain":"étudiants 是复数，泛指用复数不定冠词 des；单独 de 不能修饰名词，les 表特指，un 是单数。","source":"语法点 · 不定冠词（article indéfini） · grammar-a1a2.html#art-indef"},{"id":"q-gram-a1-0007","level":"A1","skill":"grammar","prompt":"Je bois ___ eau tous les matins.","options":["de l'","du","de la","une"],"answer":"de l'","explain":"部分冠词表「一些」，eau 以元音开头，de + le 省音为 de l'；du 只用于阳性辅音开头的名词，de la 用于阴性辅音开头，une 表「整杯/整瓶」不合「喝水」的习惯表达。","source":"语法点 · 部分冠词（article partitif） · grammar-a1a2.html#art-part"},{"id":"q-gram-a1-0008","level":"A1","skill":"grammar","prompt":"Il mange ___ pain à chaque repas.","options":["du","de la","le","des"],"answer":"du","explain":"pain 是阳性不可数名词，表「一些面包」用部分冠词 du；de la 是阴性形式，le 表「整个/特指」（此处是每餐都吃一些），des 只能修饰可数复数。","source":"语法点 · 部分冠词（article partitif） · grammar-a1a2.html#art-part"},{"id":"q-gram-a1-0009","level":"A1","skill":"grammar","prompt":"Nous avons ___ chance d'avoir un bon professeur.","options":["de la","du","une","des"],"answer":"de la","explain":"chance 是阴性不可数名词，用部分冠词 de la；du 是阳性，une 强调「一个」而 chance 在此不可数，des 只用于可数复数。","source":"语法点 · 部分冠词（article partitif） · grammar-a1a2.html#art-part"},{"id":"q-gram-a1-0010","level":"A1","skill":"grammar","prompt":"Je vais ___ cinéma ce soir.","options":["au","à le","à la","en"],"answer":"au","explain":"介词 à 与阳性单数定冠词 le 必须缩合成 au，现代法语不存在 à le；à la 用于阴性名词（cinéma 是阳性），en 用于阴性国家或地区。","source":"语法点 · 缩合冠词（articles contractés） · grammar-a1a2.html#art-contract"},{"id":"q-gram-a1-0011","level":"A1","skill":"grammar","prompt":"Elle pense ___ résultats de l'examen.","options":["aux","à les","des","au"],"answer":"aux","explain":"à + les 必须缩合为 aux；à les 不合法，des 是 de + les，au 是阳性单数。","source":"语法点 · 缩合冠词（articles contractés） · grammar-a1a2.html#art-contract"},{"id":"q-gram-a1-0012","level":"A1","skill":"grammar","prompt":"Nous revenons ___ marché.","options":["du","de le","de la","des"],"answer":"du","explain":"de + le 缩合为 du；de le 不合法，de la 用于阴性名词（marché 是阳性），des 是 de + les 复数。","source":"语法点 · 缩合冠词（articles contractés） · grammar-a1a2.html#art-contract"},{"id":"q-gram-a1-0013","level":"A1","skill":"grammar","prompt":"选出正确形式（一座漂亮的房子）：","options":["une belle maison","un belle maison","une beau maison","un beau maison"],"answer":"une belle maison","explain":"maison 是阴性单数，冠词用 une、形容词加 -e 变 belle；un 是阳性冠词，une beau 冠词与形容词性别都对不上，un beau maison 把冠词和形容词都误用成阳性。","source":"语法点 · 名词的性（genre des noms） · grammar-a1a2.html#noun-genre"},{"id":"q-gram-a1-0014","level":"A1","skill":"grammar","prompt":"J'ai acheté ___ dictionnaire.","options":["un nouveau","une nouveau","un nouvelle","une nouvelle"],"answer":"un nouveau","explain":"dictionnaire 是阳性单数，用 un nouveau；une 是阴性冠词，nouvelle 是阴性形容词形式，两个阴性选项都不能修饰阳性名词。","source":"语法点 · 名词的性（genre des noms） · grammar-a1a2.html#noun-genre"},{"id":"q-gram-a1-0015","level":"A1","skill":"grammar","prompt":"___ ville est très belle au printemps.","options":["Cette","Ce","Cet","Ces"],"answer":"Cette","explain":"ville 是阴性单数，指示形容词用 cette；ce 用于阳性单数，cet 用于元音或哑音 h 开头的阳性单数，ces 是复数。","source":"语法点 · 名词的性（genre des noms） · grammar-a1a2.html#noun-genre"},{"id":"q-gram-a1-0016","level":"A1","skill":"grammar","prompt":"une ___ robe","options":["belle","beau","bel","beaux"],"answer":"belle","explain":"robe 是阴性单数，形容词加 -e 成 belle；beau 和 bel 是阳性形式（bel 只用在元音开头的阳性名词前），beaux 是阳性复数。","source":"语法点 · 形容词性数配合（accord de l'adjectif） · grammar-a1a2.html#adj-accord"},{"id":"q-gram-a1-0017","level":"A1","skill":"grammar","prompt":"des fleurs ___","options":["blanches","blanc","blanche","blancs"],"answer":"blanches","explain":"fleurs 是阴性复数，形容词加 -es 成 blanches；blanc 是阳性单数形式，blanche 是阴性单数，blancs 是阳性复数。","source":"语法点 · 形容词性数配合（accord de l'adjectif） · grammar-a1a2.html#adj-accord"},{"id":"q-gram-a1-0018","level":"A1","skill":"grammar","prompt":"Les enfants sont ___ après la promenade.","options":["contents","content","contente","contentes"],"answer":"contents","explain":"enfants 是阳性复数，表语形容词要加 -s：contents；content 是单数，contente 是阴性单数，contentes 是阴性复数。","source":"语法点 · 形容词性数配合（accord de l'adjectif） · grammar-a1a2.html#adj-accord"},{"id":"q-gram-a1-0019","level":"A1","skill":"grammar","prompt":"Ma sœur et ma cousine sont très ___ .","options":["heureuses","heureux","heureuse","heureusement"],"answer":"heureuses","explain":"两个主语都是阴性，表语用阴性复数 heureuses；heureux 是阳性，heureuse 是阴性单数，heureusement 是副词，不能作表语。","source":"语法点 · 形容词性数配合（accord de l'adjectif） · grammar-a1a2.html#adj-accord"},{"id":"q-gram-a1-0020","level":"A1","skill":"grammar","prompt":"___ homme est mon voisin.","options":["Cet","Ce","Cette","Ces"],"answer":"Cet","explain":"homme 以哑音 h 开头，阳性单数指示形容词用 cet；ce 不能用在元音或哑音 h 前，cette 是阴性，ces 是复数。","source":"语法点 · 指示形容词（adjectif démonstratif） · grammar-a1a2.html#adj-dem"},{"id":"q-gram-a1-0021","level":"A1","skill":"grammar","prompt":"___ livres sont très intéressants.","options":["Ces","Ses","C'est","Cet"],"answer":"Ces","explain":"livres 是复数，指示形容词用 ces；ses 是主有形容词「他的/她的」，c'est 意思是「这是」，cet 只修饰阳性单数。","source":"语法点 · 指示形容词（adjectif démonstratif） · grammar-a1a2.html#adj-dem"},{"id":"q-gram-a1-0022","level":"A1","skill":"grammar","prompt":"Voici ___ sœur.（我的姐姐）","options":["ma","mon","mes","moi"],"answer":"ma","explain":"sœur 是阴性单数，主有形容词用 ma；mon 用于阳性名词或元音开头的阴性名词，mes 是复数，moi 是重读代词，不能限定名词。","source":"语法点 · 主有形容词（adjectif possessif） · grammar-a1a2.html#adj-poss"},{"id":"q-gram-a1-0023","level":"A1","skill":"grammar","prompt":"Il a perdu ___ clés.（他的钥匙）","options":["ses","son","sa","sien"],"answer":"ses","explain":"clés 是复数，主有形容词用 ses；son 和 sa 都是单数形式，sien 是主有代词「他的（东西）」，不能放在名词前。","source":"语法点 · 主有形容词（adjectif possessif） · grammar-a1a2.html#adj-poss"},{"id":"q-gram-a1-0024","level":"A1","skill":"grammar","prompt":"J'invite ___ amis ce soir.（我的朋友们）","options":["mes","ma","mon","mien"],"answer":"mes","explain":"amis 是复数，用 mes；ma 和 mon 都是单数形式，mien 是主有代词，不能作限定词。","source":"语法点 · 主有形容词（adjectif possessif） · grammar-a1a2.html#adj-poss"},{"id":"q-gram-a1-0025","level":"A1","skill":"grammar","prompt":"Il y a ___ monde sur la place.","options":["beaucoup de","beaucoup des","beaucoup du","beaucoup les"],"answer":"beaucoup de","explain":"数量副词后直接接 de + 名词，不再带冠词：beaucoup de monde；beaucoup des 只在特指（beaucoup des amis que je connais）时可用，beaucoup du 和 beaucoup les 都不成立。","source":"语法点 · 数量副词与 de（adverbes de quantité） · grammar-a1a2.html#quant-adv"},{"id":"q-gram-a1-0026","level":"A1","skill":"grammar","prompt":"Je n'ai pas ___ temps aujourd'hui.","options":["de","du","le","un"],"answer":"de","explain":"绝对否定中部分冠词 du 要变成 de：pas de temps；pas du 是中国人最常见的错法，pas le 表特指，pas un 强调「连一个都没有」，与整体否定不符。","source":"语法点 · 数量副词与 de（adverbes de quantité） · grammar-a1a2.html#quant-adv"},{"id":"q-gram-a1-0027","level":"A1","skill":"grammar","prompt":"J'ai ___ questions à vous poser.","options":["quelques","quelque","quelques de","un peu de"],"answer":"quelques","explain":"questions 是复数可数名词，用 quelques 直接修饰；quelque 只用于单数（quelque temps），quelques de 结构不成立，un peu de 只修饰不可数名词。","source":"语法点 · 数量副词与 de（adverbes de quantité） · grammar-a1a2.html#quant-adv"},{"id":"q-gram-a1-0028","level":"A1","skill":"grammar","prompt":"78 的法语写法是：","options":["soixante-dix-huit","septante-huit","soixante-huit-dix","quatre-vingt-dix-huit"],"answer":"soixante-dix-huit","explain":"法式数法中 70 是 soixante-dix，所以 78 是 soixante-dix-huit；septante 是比利时和瑞士用法，soixante-huit-dix 不是法语，quatre-vingt-dix-huit 是 98。","source":"语法点 · 基数词（nombres cardinaux） · grammar-a1a2.html#num-card"},{"id":"q-gram-a1-0029","level":"A1","skill":"grammar","prompt":"Il a ___ ans.（80 岁）","options":["quatre-vingts","quatre-vingt","huitante","quatre-vingt-dix"],"answer":"quatre-vingts","explain":"80 后面不接其他数词时写 quatre-vingts 并保留 -s；quatre-vingt 用于 81–89（如 quatre-vingt-un）；huitante 是瑞士部分地区用法；quatre-vingt-dix 是 90。","source":"语法点 · 基数词（nombres cardinaux） · grammar-a1a2.html#num-card"},{"id":"q-gram-a1-0030","level":"A1","skill":"grammar","prompt":"Il est ___ .（14 点 30 分）","options":["deux heures et demie","deux heures et demi","deux heures trente minutes","deux heures et demi-heure"],"answer":"deux heures et demie","explain":"半点用 et demie，demi 放在阴性名词 heures 后要配合加 -e；et demi 缺配合，deux heures trente minutes 混用钟点与时长说法，et demi-heure 结构不成立。","source":"语法点 · 时间与日期（l'heure et la date） · grammar-a1a2.html#heure-date"},{"id":"q-gram-a1-0031","level":"A1","skill":"grammar","prompt":"On se voit ___ .（这周一，单次约定）","options":["lundi","le lundi","à lundi","en lundi"],"answer":"lundi","explain":"指「这个/下个星期一」这一具体日子时直接写 lundi，不加冠词；le lundi 表示「每逢周一」的习惯，à lundi 和 en lundi 搭配错误。","source":"语法点 · 时间与日期（l'heure et la date） · grammar-a1a2.html#heure-date"},{"id":"q-gram-a1-0032","level":"A1","skill":"grammar","prompt":"Nous sommes ___ .（5 月 1 日）","options":["le premier mai","le un mai","au premier mai","la première mai"],"answer":"le premier mai","explain":"日期前用定冠词 le，1 日写序数词 premier（première 只用于阴性名词）；le un mai 不是法语说法，au 和 à la 不能引导日期。","source":"语法点 · 时间与日期（l'heure et la date） · grammar-a1a2.html#heure-date"},{"id":"q-gram-a1-0033","level":"A1","skill":"grammar","prompt":"___ est mon amie.（她）","options":["Elle","Il","Eux","Lui"],"answer":"Elle","explain":"主语位置必须用主语代词 elle；il 是阳性，eux 和 lui 是重读代词，只能用于介词后、强调或省略句中。","source":"语法点 · 主语代词（pronoms sujets） · grammar-a1a2.html#pro-subj"},{"id":"q-gram-a1-0034","level":"A1","skill":"grammar","prompt":"___ allons au parc cet après-midi.","options":["Nous","On","Vous","Ils"],"answer":"Nous","explain":"动词 allons 对应 nous；on 后面只能接第三人称单数 va，vous 对应 allez，ils 对应 vont。","source":"语法点 · 主语代词（pronoms sujets） · grammar-a1a2.html#pro-subj"},{"id":"q-gram-a1-0035","level":"A1","skill":"grammar","prompt":"Ce cadeau est pour ___ .（我）","options":["moi","me","je","mon"],"answer":"moi","explain":"介词 pour 后必须用重读代词 moi；me 是直接/间接宾语代词，je 是主语代词，mon 是主有形容词，都不能放在介词后。","source":"语法点 · 重读代词（pronoms toniques） · grammar-a1a2.html#pro-tonic"},{"id":"q-gram-a1-0036","level":"A1","skill":"grammar","prompt":"Elle est plus grande que ___ .（他）","options":["lui","il","le","son"],"answer":"lui","explain":"比较级的 que 后面用重读代词 lui；il 只能作主语，le 是直接宾语代词，son 是主有形容词。","source":"语法点 · 重读代词（pronoms toniques） · grammar-a1a2.html#pro-tonic"},{"id":"q-gram-a1-0037","level":"A1","skill":"grammar","prompt":"Tu connais Marie ? — Oui, je ___ connais bien.","options":["la","lui","le","les"],"answer":"la","explain":"connaître 直接接人，Marie 是阴性单数，直接宾语代词用 la；lui 是间接宾语代词（téléphoner à qqn 那类才用），le 是阳性，les 是复数。","source":"语法点 · 直接宾语代词 COD（pronoms compléments d'objet direct） · grammar-a1a2.html#pro-cod"},{"id":"q-gram-a1-0038","level":"A1","skill":"grammar","prompt":"Ces livres, je ___ ai déjà lus.","options":["les","leur","le","la"],"answer":"les","explain":"livres 是阳性复数直接宾语，用 les，而且复合过去时过去分词要与前置直接宾语配合加 -s；leur 是间接宾语代词，le 和 la 是单数。","source":"语法点 · 直接宾语代词 COD（pronoms compléments d'objet direct） · grammar-a1a2.html#pro-cod"},{"id":"q-gram-a1-0039","level":"A1","skill":"grammar","prompt":"Elle ___ invite à dîner.（邀请我）","options":["m'","te","se","moi"],"answer":"m'","explain":"变位动词 invite 以元音开头，me 必须省音成 m'；te 指「你」，se 是第三人称自反代词，moi 是重读代词，不能直接放在动词前。","source":"语法点 · 直接宾语代词 COD（pronoms compléments d'objet direct） · grammar-a1a2.html#pro-cod"},{"id":"q-gram-a1-0040","level":"A1","skill":"grammar","prompt":"Tu as téléphoné à tes parents ? — Oui, je ___ ai téléphoné.","options":["leur","leurs","les","lui"],"answer":"leur","explain":"téléphoner à qqn 用间接宾语代词，parents 是复数，所以用 leur；leurs 是主有形容词「他们的」，les 是直接宾语代词，lui 是单数形式。","source":"语法点 · 间接宾语代词 COI（pronoms compléments d'objet indirect） · grammar-a1a2.html#pro-coi"},{"id":"q-gram-a1-0041","level":"A1","skill":"grammar","prompt":"Il ___ a donné un livre à Marie.","options":["lui","la","le","leur"],"answer":"lui","explain":"donner qch à qqn 中 à Marie 用间接宾语代词 lui；la 和 le 是直接宾语代词，leur 是复数形式，与单数的 Marie 不符。","source":"语法点 · 间接宾语代词 COI（pronoms compléments d'objet indirect） · grammar-a1a2.html#pro-coi"},{"id":"q-gram-a1-0042","level":"A1","skill":"grammar","prompt":"Le professeur ___ explique la règle aux élèves.","options":["leur","leurs","les","lui"],"answer":"leur","explain":"à + 复数人用 leur；leurs 是主有形容词，les 是直接宾语代词（expliquer qch à qqn 是间接结构），lui 是单数。","source":"语法点 · 间接宾语代词 COI（pronoms compléments d'objet indirect） · grammar-a1a2.html#pro-coi"},{"id":"q-gram-a1-0043","level":"A1","skill":"grammar","prompt":"Nous ___ le français tous les jours.（parler）","options":["parlons","parlont","parlions","parle"],"answer":"parlons","explain":"第一组动词 nous 形式词尾是 -ons；parlont 是照搬第三人称 -ont 的臆造形式，parlions 是未完成过去时（词尾 -ions），parle 是 je / il 形式。","source":"语法点 · 第一组动词现在时（présent des verbes en -er） · grammar-a1a2.html#pres-er"},{"id":"q-gram-a1-0044","level":"A1","skill":"grammar","prompt":"Ils ___ à Lyon.（habiter）","options":["habitent","habites","habitons","habitiez"],"answer":"habitent","explain":"ils 形式词尾是 -ent；habites 是 tu 形式，habitons 是 nous 形式，habitiez 是 vous 形式。","source":"语法点 · 第一组动词现在时（présent des verbes en -er） · grammar-a1a2.html#pres-er"},{"id":"q-gram-a1-0045","level":"A1","skill":"grammar","prompt":"Tu ___ tes devoirs avant le dîner.（commencer）","options":["commences","commence","commencez","commençons"],"answer":"commences","explain":"tu 形式词尾是 -es；commence 是 je / il 形式，commencez 是 vous 形式，commençons 是 nous 形式（c 在 o 前才变 ç）。","source":"语法点 · 第一组动词现在时（présent des verbes en -er） · grammar-a1a2.html#pres-er"},{"id":"q-gram-a1-0046","level":"A1","skill":"grammar","prompt":"Nous ___ nos exercices.（finir）","options":["finissons","finons","finis","finissent"],"answer":"finissons","explain":"第二组动词 nous 形式必须插入 -iss-：finissons；finons 漏掉 -iss-（误按第一组变位），finis 是 je / tu 形式，finissent 是 ils 形式。","source":"语法点 · 第二组动词现在时（présent des verbes en -ir） · grammar-a1a2.html#pres-ir"},{"id":"q-gram-a1-0047","level":"A1","skill":"grammar","prompt":"Elle ___ ses études à Paris.（réussir）","options":["réussit","réussis","réussie","réussir"],"answer":"réussit","explain":"il / elle 形式以 -it 结尾；réussis 是 je / tu 形式，réussie 是过去分词阴性，不能单独作谓语，réussir 是原形。","source":"语法点 · 第二组动词现在时（présent des verbes en -ir） · grammar-a1a2.html#pres-ir"},{"id":"q-gram-a1-0048","level":"A1","skill":"grammar","prompt":"Je ___ à la maison ce soir.（être）","options":["suis","es","est","sommes"],"answer":"suis","explain":"être 的 je 形式是 suis；es 是 tu 形式，est 是 il / elle 形式，sommes 是 nous 形式。","source":"语法点 · 不规则动词现在时（verbes irréguliers au présent） · grammar-a1a2.html#pres-irreg"},{"id":"q-gram-a1-0049","level":"A1","skill":"grammar","prompt":"Tu ___ quel âge ?（avoir）","options":["as","a","ai","avons"],"answer":"as","explain":"avoir 的 tu 形式是 as；a 是 il / elle 形式，ai 是 je 形式，avons 是 nous 形式。","source":"语法点 · 不规则动词现在时（verbes irréguliers au présent） · grammar-a1a2.html#pres-irreg"},{"id":"q-gram-a1-0050","level":"A1","skill":"grammar","prompt":"Nous ___ au marché le samedi.（aller）","options":["allons","allez","vont","vais"],"answer":"allons","explain":"aller 的 nous 形式是 allons；allez 是 vous 形式，vont 是 ils 形式，vais 是 je 形式。","source":"语法点 · 不规则动词现在时（verbes irréguliers au présent） · grammar-a1a2.html#pres-irreg"},{"id":"q-gram-a1-0051","level":"A1","skill":"grammar","prompt":"Ils ___ leurs devoirs ensemble.（faire）","options":["font","faisons","faites","fais"],"answer":"font","explain":"faire 的 ils 形式是 font；faisons 是 nous 形式，faites 是 vous 形式，fais 是 je / tu 形式。","source":"语法点 · 不规则动词现在时（verbes irréguliers au présent） · grammar-a1a2.html#pres-irreg"},{"id":"q-gram-a1-0052","level":"A1","skill":"grammar","prompt":"Vous ___ venir demain ?（pouvoir）","options":["pouvez","peux","peut","pouvons"],"answer":"pouvez","explain":"pouvoir 的 vous 形式是 pouvez；peux 是 je / tu 形式，peut 是 il / elle 形式，pouvons 是 nous 形式。","source":"语法点 · 不规则动词现在时（verbes irréguliers au présent） · grammar-a1a2.html#pres-irreg"},{"id":"q-gram-a1-0053","level":"A1","skill":"grammar","prompt":"___ tes devoirs avant de sortir !（tu + faire，命令式）","options":["Fais","Fait","Faites","Faire"],"answer":"Fais","explain":"命令式 tu 形式不写主语，faire 的 tu 命令式是不规则的 fais；fait 是直陈式 il 形式，faites 是 vous 命令式，faire 是原形。","source":"语法点 · 命令式（impératif） · grammar-a1a2.html#imperatif"},{"id":"q-gram-a1-0054","level":"A1","skill":"grammar","prompt":"___ sages, les enfants !（vous + être，命令式）","options":["Soyez","Êtes","Sont","Sois"],"answer":"Soyez","explain":"être 的 vous 命令式是 Soyez；Êtes 是直陈式形式（命令式不用），Sont 是 ils 形式，Sois 是 tu 命令式。","source":"语法点 · 命令式（impératif） · grammar-a1a2.html#imperatif"},{"id":"q-gram-a1-0055","level":"A1","skill":"grammar","prompt":"___ , s'il te plaît.（把它给我：tu + donner + le + moi）","options":["Donne-le-moi","Donne-moi-le","Me-le-donne","Donne le moi"],"answer":"Donne-le-moi","explain":"肯定命令式中直接宾语代词排在间接宾语代词之前，并用连字符：donne-le-moi；donne-moi-le 语序颠倒，me-le-donne 是陈述句语序，donne le moi 缺连字符。","source":"语法点 · 命令式（impératif） · grammar-a1a2.html#imperatif"},{"id":"q-gram-a1-0056","level":"A1","skill":"grammar","prompt":"Je ___ parle pas anglais.","options":["ne","n'","pas","non"],"answer":"ne","explain":"ne…pas 夹住变位动词，parle 以辅音开头所以用 ne；n' 只用于元音或哑音 h 开头的词前，pas 只能作否定第二部分，non 是回答词。","source":"语法点 · 否定（la négation） · grammar-a1a2.html#negation"},{"id":"q-gram-a1-0057","level":"A1","skill":"grammar","prompt":"选出语法正确的句子：","options":["Je n'ai pas faim.","Je n'ai faim pas.","Je pas ai faim.","J'ai pas de faim."],"answer":"Je n'ai pas faim.","explain":"ne…pas 要夹住变位动词 ai；faim 在这个固定表达里不带冠词，所以 pas de faim 搭配错误，另外两句 ne / pas 的位置也错。","source":"语法点 · 否定（la négation） · grammar-a1a2.html#negation"},{"id":"q-gram-a1-0058","level":"A1","skill":"grammar","prompt":"Personne ___ répondu au téléphone hier.","options":["n'a","a","ne pas a","n'est"],"answer":"n'a","explain":"主语 personne 本身表否定，但动词仍要加 ne：personne n'a répondu；répondre 用 avoir 作助动词，所以 n'est 错；单独 a 缺 ne。","source":"语法点 · 否定（la négation） · grammar-a1a2.html#negation"},{"id":"q-gram-a1-0059","level":"A1","skill":"grammar","prompt":"Tu ne bois jamais ___ café ?","options":["de","du","le","un"],"answer":"de","explain":"否定词 jamais 构成绝对否定，部分冠词 du 要变成 de；du 是肯定式，le 表特指，un 表「一杯」，都与「从来不喝咖啡」的整体否定不符。","source":"语法点 · 否定（la négation） · grammar-a1a2.html#negation"},{"id":"q-gram-a1-0060","level":"A1","skill":"grammar","prompt":"用 est-ce que 改写 Tu parles français ? 正确形式是：","options":["Est-ce que tu parles français ?","Est-ce que parles-tu français ?","Parles-tu est-ce que français ?","Tu est-ce que parles français ?"],"answer":"Est-ce que tu parles français ?","explain":"est-ce que 后面必须接陈述语序（主语 + 变位动词）；Est-ce que parles-tu 把 est-ce que 与倒装混用，另外两句语序错误。","source":"语法点 · 疑问句（l'interrogation） · grammar-a1a2.html#interrogation"},{"id":"q-gram-a1-0061","level":"A1","skill":"grammar","prompt":"— J'habite à Paris. — ___ est-ce que tu habites ?","options":["Où","Quand","Qui","Comment"],"answer":"Où","explain":"问地点用 où；quand 问时间，qui 问人，comment 问方式，都与答语 à Paris 不符。","source":"语法点 · 疑问句（l'interrogation） · grammar-a1a2.html#interrogation"},{"id":"q-gram-a1-0062","level":"A1","skill":"grammar","prompt":"把 Vous êtes français ? 改成正式倒装疑问句：","options":["Êtes-vous français ?","Vous êtes-vous français ?","Êtes-vous que français ?","Vous-êtes français ?"],"answer":"Êtes-vous français ?","explain":"倒装时变位动词在前、主语代词在后并加连字符：Êtes-vous；Vous êtes-vous 多了一个代词，Êtes-vous que 多出 que，Vous-êtes 没有倒装。","source":"语法点 · 疑问句（l'interrogation） · grammar-a1a2.html#interrogation"},{"id":"q-gram-a1-0063","level":"A1","skill":"grammar","prompt":"Demain, nous ___ visiter le musée.","options":["allons","allez","vont","allions"],"answer":"allons","explain":"最近将来时是 aller 的现在时 + 不定式，主语 nous 用 allons；allez 是 vous 形式，vont 是 ils 形式，allions 是未完成过去时。","source":"语法点 · 最近将来时（futur proche） · grammar-a1a2.html#futur-proche"},{"id":"q-gram-a1-0064","level":"A1","skill":"grammar","prompt":"Je ___ partir dans cinq minutes.","options":["vais","vas","va","allons"],"answer":"vais","explain":"aller 的 je 形式是 vais；vas 是 tu 形式，va 是 il / elle 形式，allons 是 nous 形式。","source":"语法点 · 最近将来时（futur proche） · grammar-a1a2.html#futur-proche"},{"id":"q-gram-a1-0065","level":"A1","skill":"grammar","prompt":"Elle ___ se marier en juin.","options":["va","vas","vais","vont"],"answer":"va","explain":"elle 对应 va；vas 是 tu 形式，vais 是 je 形式，vont 是 ils / elles 形式。","source":"语法点 · 最近将来时（futur proche） · grammar-a1a2.html#futur-proche"},{"id":"q-gram-a1-0066","level":"A1","skill":"grammar","prompt":"Je vais ___ Japon l'année prochaine.","options":["au","en","à","dans"],"answer":"au","explain":"阳性国家名前用 au（le Japon → au Japon）；en 用于阴性国家（en France），à 后接城市，dans 强调「在某空间内部」。","source":"语法点 · 地点介词（prépositions de lieu） · grammar-a1a2.html#prep-lieu"},{"id":"q-gram-a1-0067","level":"A1","skill":"grammar","prompt":"Nous habitons ___ Paris depuis trois ans.","options":["à","en","au","dans le"],"answer":"à","explain":"城市前用 à；en 用于阴性国家，au 用于阳性国家，dans le 强调「在……内部」，不用于居住在城市。","source":"语法点 · 地点介词（prépositions de lieu） · grammar-a1a2.html#prep-lieu"},{"id":"q-gram-a1-0068","level":"A1","skill":"grammar","prompt":"Le livre est ___ la table.","options":["sur","dans","à","chez"],"answer":"sur","explain":"表示「在……上面」用 sur；dans 是「在……里面」，à la table 指「在桌边」而不是「在桌上」，chez 只能接人。","source":"语法点 · 地点介词（prépositions de lieu） · grammar-a1a2.html#prep-lieu"}],"listening":[{"id":"q-listen-a1-0001","level":"A1","skill":"listening","prompt":"[听力原文] Bonjour, je m'appelle Léa. J'ai vingt ans et j'étudie le français. 问题：Léa a quel âge ?","options":["Vingt ans","Douze ans","Trente ans","Deux ans"],"answer":"Vingt ans","explain":"原文是 j'ai vingt ans（20 岁）；douze（12）、trente（30）、deux（2）都是相近的数字干扰，注意 vingt [vɛ̃] 的鼻化元音。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0002","level":"A1","skill":"listening","prompt":"[听力原文] — Vous habitez où ? — J'habite à Lyon, près de la gare. 问题：Où habite cette personne ?","options":["À Lyon","À Paris","À Lille","À Nice"],"answer":"À Lyon","explain":"原文明确说 j'habite à Lyon；Paris、Lille、Nice 都是法国常见城市名，考的是能否分辨 [ljɔ̃]。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0003","level":"A1","skill":"listening","prompt":"[听力原文] — Tu veux du thé ou du café ? — Du café, s'il te plaît. 问题：Qu'est-ce que la personne demande ?","options":["Un café","Un thé","De l'eau","Un jus d'orange"],"answer":"Un café","explain":"回答是 du café；thé 只是问句中的另一个选项，eau 和 jus d'orange 都没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0004","level":"A1","skill":"listening","prompt":"[听力原文] Aujourd'hui, il fait beau et chaud. Demain, il va pleuvoir. 问题：Quel temps fera-t-il demain ?","options":["Il va pleuvoir","Il fera beau","Il va neiger","Il fera froid"],"answer":"Il va pleuvoir","explain":"demain 对应 il va pleuvoir（要下雨）；il fait beau 是今天，neiger 和 froid 都没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0005","level":"A1","skill":"listening","prompt":"[听力原文] Le musée ouvre à neuf heures et ferme à dix-huit heures. 问题：À quelle heure ouvre le musée ?","options":["À neuf heures","À dix-huit heures","À dix heures","À huit heures"],"answer":"À neuf heures","explain":"ouvrir 对应 neuf heures（9 点）；dix-huit heures 是关门时间，dix heures 与 huit heures 都是邻近数字干扰。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0006","level":"A1","skill":"listening","prompt":"[听力原文] — Ça fait combien ? — Douze euros cinquante. 问题：Combien ça coûte ?","options":["Douze euros cinquante","Vingt euros","Douze euros","Deux euros cinquante"],"answer":"Douze euros cinquante","explain":"听到的是 douze euros cinquante（12,50 欧）；漏掉 cinquante 或把 douze 听成 deux 都会选错，vingt 是 20。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0007","level":"A1","skill":"listening","prompt":"[听力原文] J'ai deux frères et une sœur. 问题：Combien d'enfants y a-t-il en tout dans la famille ?","options":["Quatre","Trois","Deux","Cinq"],"answer":"Quatre","explain":"两个兄弟加一个妹妹，再加上说话人本人共四个孩子；只数 frères et sœur 会误选 trois。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0008","level":"A1","skill":"listening","prompt":"[听力原文] — Tu prends le bus pour aller au travail ? — Non, je vais à pied. 问题：Comment va-t-elle au travail ?","options":["À pied","En bus","En voiture","En métro"],"answer":"À pied","explain":"回答是 je vais à pied（步行）；en bus 是被否定掉的选项，voiture 和 métro 在原文里没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0009","level":"A1","skill":"listening","prompt":"[听力原文] Mon anniversaire est le trois mai. 问题：Quand est son anniversaire ?","options":["Le 3 mai","Le 13 mai","Le 30 mai","Le 3 mars"],"answer":"Le 3 mai","explain":"le trois mai（5 月 3 日）；treize 是 13，trente 是 30，mars 是三月，都是数字或月份干扰。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0010","level":"A1","skill":"listening","prompt":"[听力原文] — Allô ? Je voudrais réserver une table pour deux personnes à vingt heures. 问题：Pour combien de personnes veut-elle réserver ?","options":["Deux","Douze","Trois","Quatre"],"answer":"Deux","explain":"pour deux personnes 是两人桌；douze（12）与 deux（2）音形都近，是典型干扰。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0011","level":"A1","skill":"listening","prompt":"[听力原文] — Excusez-moi, où est la banque ? — Tout droit, puis à gauche. 问题：Où se trouve la banque ?","options":["Tout droit puis à gauche","Tout droit puis à droite","À droite puis à gauche","Derrière vous"],"answer":"Tout droit puis à gauche","explain":"原文是 tout droit, puis à gauche；把 gauche（左）与 droite（右）听反是最常见的错误。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0012","level":"A1","skill":"listening","prompt":"[听力原文] Je me lève à sept heures et je prends mon petit déjeuner à sept heures et demie. 问题：À quelle heure prend-il son petit déjeuner ?","options":["À sept heures et demie","À sept heures","À huit heures","À six heures et demie"],"answer":"À sept heures et demie","explain":"petit déjeuner 对应 sept heures et demie（7 点半）；sept heures 是起床时间，两个信息要分开抓。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0013","level":"A1","skill":"listening","prompt":"[听力原文] — Vous avez des pommes ? — Oui, elles sont à deux euros le kilo. 问题：Combien coûtent les pommes ?","options":["Deux euros le kilo","Deux euros la pièce","Douze euros le kilo","Deux euros les deux kilos"],"answer":"Deux euros le kilo","explain":"à deux euros le kilo（每公斤 2 欧）；la pièce（每个）和 les deux kilos 都改变了计价方式。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0014","level":"A1","skill":"listening","prompt":"[听力原文] Je ne mange pas de viande, mais je mange du poisson. 问题：Qu'est-ce que la personne mange ?","options":["Du poisson","De la viande","Ni viande ni poisson","Du poulet"],"answer":"Du poisson","explain":"前半句否定 viande，后半句肯定 poisson（鱼）；poulet（鸡肉）属于肉类，原文没有提到。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0015","level":"A1","skill":"listening","prompt":"[听力原文] Il y a un problème : mon train a du retard de vingt minutes. 问题：Quel est le problème ?","options":["Le train a vingt minutes de retard","Le train est annulé","Il a perdu son billet","Il s'est trompé de gare"],"answer":"Le train a vingt minutes de retard","explain":"un retard de vingt minutes（晚点 20 分钟）；annulé（取消）、perdre son billet（丢票）、se tromper de gare（走错车站）都没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0016","level":"A1","skill":"listening","prompt":"[听力原文] — Tu vas au cinéma ce soir ? — Non, je suis fatigué, je reste à la maison. 问题：Que va faire cette personne ce soir ?","options":["Elle reste à la maison","Elle va au cinéma","Elle va au restaurant","Elle travaille"],"answer":"Elle reste à la maison","explain":"回答 non 加 je reste à la maison；cinéma 被否定，restaurant 和 travailler 都没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0017","level":"A1","skill":"listening","prompt":"[听力原文] Paul travaille dans un hôpital. Il est médecin. 问题：Quelle est la profession de Paul ?","options":["Médecin","Infirmier","Professeur","Vendeur"],"answer":"Médecin","explain":"原文说 il est médecin（医生）；hôpital 只是工作地点，infirmier（护士）等其他职业没有出现。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"},{"id":"q-listen-a1-0018","level":"A1","skill":"listening","prompt":"[听力原文] Nous sommes en hiver, il fait froid et il neige. 问题：Quelle est la saison ?","options":["L'hiver","L'été","Le printemps","L'automne"],"answer":"L'hiver","explain":"原文 en hiver（冬天）并说 il fait froid, il neige；été、printemps、automne 都不符。","source":"听力 · A1 日常对话（compréhension orale A1 · DELF）"}],"reading":[{"id":"q-read-a1-0001","level":"A1","skill":"reading","prompt":"[阅读] Bonjour, je m'appelle Karim. J'ai 25 ans et je suis étudiant. J'habite à Bordeaux avec ma sœur. 问题：Où habite Karim ?","options":["À Bordeaux","À Paris","À Lyon","À Marseille"],"answer":"À Bordeaux","explain":"原文说 j'habite à Bordeaux avec ma sœur；Paris 和 Lyon 没有出现，文中是跟姐姐住而不是父母。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0002","level":"A1","skill":"reading","prompt":"[阅读] Fermé le dimanche et les jours fériés. Ouvert du lundi au samedi, de 9 h à 19 h. 问题：Quand le magasin est-il ouvert ?","options":["Du lundi au samedi","Le dimanche","Tous les jours","Seulement le matin"],"answer":"Du lundi au samedi","explain":"ouvert du lundi au samedi；dimanche 和 jours fériés 都关门，「只有上午营业」与 9 h-19 h 矛盾。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0003","level":"A1","skill":"reading","prompt":"[阅读] Menu du jour : soupe à l'oignon, poulet rôti avec des pommes de terre, tarte aux pommes. 15 €. 问题：Que comprend ce menu ?","options":["Une soupe, du poulet et une tarte","Du poisson et une salade","Une pizza et une glace","Un steak et du fromage"],"answer":"Une soupe, du poulet et une tarte","explain":"逐项对应 soupe à l'oignon、poulet rôti、tarte aux pommes；其他菜名都是替换干扰。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0004","level":"A1","skill":"reading","prompt":"[阅读] Chère Julie, je t'invite à mon anniversaire samedi 12 juin à 19 heures chez moi. Apporte ton CD préféré ! À bientôt, Emma. 问题：Quand a lieu l'anniversaire ?","options":["Le samedi 12 juin à 19 heures","Le dimanche 12 juin","Le samedi 12 juillet","Le samedi à midi"],"answer":"Le samedi 12 juin à 19 heures","explain":"时间信息完整：samedi 12 juin à 19 heures；星期、日期、月份、时刻四处都可能被改错。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0005","level":"A1","skill":"reading","prompt":"[阅读] Le train pour Marseille part à 10 h 15, voie 7. 问题：Quel est le numéro du quai ?","options":["Voie 7","Voie 15","Voie 10","Voie 17"],"answer":"Voie 7","explain":"voie 7 是站台号；15 和 10 来自发车时刻，17 是把时间与站台号拼在一起的错误。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0006","level":"A1","skill":"reading","prompt":"[阅读] J'ai mal à la gorge et je tousse. Je vais voir le médecin cet après-midi. 问题：Pourquoi va-t-elle voir le médecin ?","options":["Parce qu'elle a mal à la gorge","Parce qu'elle a mal au dos","Parce qu'elle veut un certificat","Parce qu'elle est fatiguée"],"answer":"Parce qu'elle a mal à la gorge","explain":"症状是 mal à la gorge 和 tousse；背痛、开证明、疲劳在文中都没有出现。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0007","level":"A1","skill":"reading","prompt":"[阅读] Appartement à louer : deux pièces, 45 m², 5e étage avec ascenseur. 680 € par mois, charges comprises. 问题：Que comprend le loyer ?","options":["Les charges","Le parking","Les meubles","Internet"],"answer":"Les charges","explain":"charges comprises 指租金包含物业杂费；停车位、家具、网络都没有提到。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0008","level":"A1","skill":"reading","prompt":"[阅读] Je prends mon petit déjeuner à 7 h, je commence le travail à 8 h 30 et je déjeune à midi. 问题：À quelle heure commence-t-elle le travail ?","options":["À 8 h 30","À 7 h","À midi","À 9 h 30"],"answer":"À 8 h 30","explain":"commence le travail 对应 8 h 30；7 h 是早餐，midi 是午餐，9 h 30 是邻近时间干扰。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0009","level":"A1","skill":"reading","prompt":"[阅读] Aujourd'hui, il fait beau. Demain, il pleuvra et il fera plus frais. 问题：Quel temps fera-t-il demain ?","options":["Il pleuvra et il fera plus frais","Il fera beau et chaud","Il neigera","Il y aura du vent"],"answer":"Il pleuvra et il fera plus frais","explain":"demain 对应 pleuvra 和 plus frais；beau et chaud 是今天，neige 和 vent 都没有出现。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0010","level":"A1","skill":"reading","prompt":"[阅读] Je voudrais un kilo de tomates et trois pommes, s'il vous plaît. 问题：Qu'est-ce qu'il achète ?","options":["Des tomates et des pommes","Des pommes de terre","Des oranges","Du pain"],"answer":"Des tomates et des pommes","explain":"清单是 tomates 和 pommes；pommes de terre（土豆）与 pommes（苹果）是最经典的混淆，oranges 和 pain 没有提到。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0011","level":"A1","skill":"reading","prompt":"[阅读] Mes grands-parents habitent à la campagne, dans une petite maison avec un grand jardin. 问题：Où habitent ses grands-parents ?","options":["À la campagne","En ville","Dans un appartement","Près de la mer"],"answer":"À la campagne","explain":"原文说 à la campagne，住的是带花园的小房子；城里、公寓、海边都不符。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0012","level":"A1","skill":"reading","prompt":"[阅读] La piscine municipale est ouverte de 10 h à 20 h. Entrée : 4 € pour les adultes, 2 € pour les enfants. 问题：Combien paie un enfant ?","options":["2 €","4 €","6 €","C'est gratuit"],"answer":"2 €","explain":"儿童票 2 €，成人票 4 €；6 € 是把两者相加的错误，免费与原文矛盾。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0013","level":"A1","skill":"reading","prompt":"[阅读] Je cherche un cadeau pour ma mère. Elle aime les fleurs et la musique. 问题：Quel cadeau est le plus adapté ?","options":["Des fleurs ou un CD","Un livre de cuisine","Des chaussures de sport","Un ordinateur"],"answer":"Des fleurs ou un CD","explain":"母亲喜欢 fleurs 和 musique，所以花或音乐 CD 合适；其他礼物与她的兴趣无关。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0014","level":"A1","skill":"reading","prompt":"[阅读] Bonjour, je suis désolé, je ne peux pas venir à la réunion de demain : je suis en voyage à Nice. 问题：Pourquoi ne peut-il pas venir ?","options":["Il est en voyage","Il est malade","Il a un autre rendez-vous","Il a oublié la réunion"],"answer":"Il est en voyage","explain":"原文说 je suis en voyage à Nice；生病、另有约会、忘记开会都没有依据。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0015","level":"A1","skill":"reading","prompt":"[阅读] Dans mon quartier, il y a une boulangerie, une pharmacie et un petit marché le samedi matin. 问题：Qu'est-ce qu'il y a dans ce quartier ?","options":["Une boulangerie, une pharmacie et un marché","Un cinéma et une bibliothèque","Un hôpital et une école","Seulement un supermarché"],"answer":"Une boulangerie, une pharmacie et un marché","explain":"三项都在原文里；cinéma、bibliothèque、hôpital、école、supermarché 都没有出现。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0016","level":"A1","skill":"reading","prompt":"[阅读] J'apprends le français depuis six mois. Je prends des cours deux fois par semaine. 问题：Depuis combien de temps apprend-elle le français ?","options":["Depuis six mois","Depuis deux semaines","Depuis six ans","Depuis deux mois"],"answer":"Depuis six mois","explain":"depuis six mois（六个月）；deux 是每周上课次数，six ans 把月与年混淆。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0017","level":"A1","skill":"reading","prompt":"[阅读] Attention : le musée est fermé pour travaux jusqu'au 15 septembre. 问题：Pourquoi le musée est-il fermé ?","options":["Pour travaux","Pour les vacances","Parce qu'il est trop petit","Parce qu'il n'y a pas de visiteurs"],"answer":"Pour travaux","explain":"fermé pour travaux（因施工关闭）；vacances、taille、visiteurs 都没有出现。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"},{"id":"q-read-a1-0018","level":"A1","skill":"reading","prompt":"[阅读] Mon frère a un chien et deux chats. Il adore les animaux. 问题：Combien d'animaux a-t-il en tout ?","options":["Trois","Deux","Un","Quatre"],"answer":"Trois","explain":"一只狗加两只猫共三只；只数猫会选 deux，只数狗会选 un。","source":"阅读 · A1 通知与短信（compréhension écrite A1 · DELF）"}],"writing":[{"id":"q-writ-a1-0001","level":"A1","skill":"writing","prompt":"写作自评（自我介绍），选出正确的一句：","options":["Je m'appelle Li Ming et j'ai vingt ans.","Je m'appelle Li Ming et je suis vingt ans.","Je m'appelle Li Ming et j'ai vingt année.","Je m'appelle Li Ming et j'ai vingt ans de vieux."],"answer":"Je m'appelle Li Ming et j'ai vingt ans.","explain":"年龄用 avoir + 数字 + ans（复数）：j'ai vingt ans；je suis vingt ans 是中文式直译，année 指时段不表岁数，「ans de vieux」不是法语表达。自评标准：能正确使用年龄句式。","source":"写作自评 · A1 自我介绍（production écrite A1）"},{"id":"q-writ-a1-0002","level":"A1","skill":"writing","prompt":"写作自评（说明居住地），选出正确的一句：","options":["J'habite à Shanghai, en Chine.","Je habite à Shanghai, en Chine.","J'habite à Shanghai, au Chine.","J'habite à Shanghai, dans Chine."],"answer":"J'habite à Shanghai, en Chine.","explain":"元音开头的动词前 je 要省音为 j'；阴性国家名前用 en（la Chine → en Chine），au 用于阳性国家（au Japon），dans 不能直接接国名。","source":"写作自评 · A1 自我介绍（production écrite A1）"},{"id":"q-writ-a1-0003","level":"A1","skill":"writing","prompt":"写作自评（家庭成员），选出正确的一句：","options":["Ma famille est petite : mes parents, ma sœur et moi.","Ma famille est petite : mes parents, ma sœur et je.","Ma famille est petite : mes parents, ma sœur et me.","Ma famille est petite : mes parents, ma sœur et mon."],"answer":"Ma famille est petite : mes parents, ma sœur et moi.","explain":"并列成分末尾要用重读代词 moi；je 只能作主语（不能并列在介词/列举之后），me 是宾语代词，mon 是主有形容词不能独立使用。","source":"写作自评 · A1 家庭与介绍（production écrite A1）"},{"id":"q-writ-a1-0004","level":"A1","skill":"writing","prompt":"写作自评（写明信片谈天气），选出正确的一句：","options":["Il fait beau et chaud, nous sommes très contents.","Il fait beau et chaud, nous sommes très content.","Il fait beau et chaud, nous avons très contents.","Il fait beau et chaud, nous sommes très contente."],"answer":"Il fait beau et chaud, nous sommes très contents.","explain":"表语形容词要与 nous 的阳性复数配合 contents；content 缺复数，avoir 不能带形容词表语，contente 是阴性单数（主语含男性时不适用）。","source":"写作自评 · A1 明信片（production écrite A1）"},{"id":"q-writ-a1-0005","level":"A1","skill":"writing","prompt":"写作自评（礼貌请求信息），选出最得体的一句：","options":["Pourriez-vous m'envoyer le programme, s'il vous plaît ?","Pouvez-vous m'envoyer le programme, s'il te plaît ?","Pourriez-vous m'envoyez le programme, s'il vous plaît ?","Pourriez-vous envoyer-moi le programme ?"],"answer":"Pourriez-vous m'envoyer le programme, s'il vous plaît ?","explain":"条件式 Pourriez-vous 表礼貌，后接不定式 envoyer；s'il te plaît 与 vous 人称不一致，m'envoyez 是变位形式（不能跟在条件式后），envoyer-moi 在非命令式中代词要前置为 m'envoyer。","source":"写作自评 · A1 电子邮件（production écrite A1）"},{"id":"q-writ-a1-0006","level":"A1","skill":"writing","prompt":"写作自评（叙述昨天），选出正确的一句：","options":["Hier, je suis allé au cinéma avec mes amis.","Hier, j'ai allé au cinéma avec mes amis.","Hier, je suis allé au cinéma avec mes amie.","Hier, je suis allé au cinéma avec mon amis."],"answer":"Hier, je suis allé au cinéma avec mes amis.","explain":"aller 用 être 作助动词（j'ai allé 是最常见错误）；amis 是复数，主有形容词要用 mes 且名词带 -s（mes amie / mon amis 都错）。","source":"写作自评 · A1 日记（production écrite A1）"},{"id":"q-writ-a1-0007","level":"A1","skill":"writing","prompt":"写作自评（写课程时间），选出正确的一句：","options":["Le cours commence à neuf heures.","Le cours commence à neuf heure.","Le cours commence dans neuf heures.","Le cours commence en neuf heures."],"answer":"Le cours commence à neuf heures.","explain":"钟点用 à + heures（复数形）：à neuf heures；heure 单数是拼写错误，dans neuf heures 意思是「九小时以后」，en neuf heures 意思是「用九小时」。","source":"写作自评 · A1 课程信息（production écrite A1）"},{"id":"q-writ-a1-0008","level":"A1","skill":"writing","prompt":"写作自评（写地址），选出正确的一句：","options":["J'habite au 12, rue Victor-Hugo.","J'habite à 12, rue Victor-Hugo.","J'habite dans 12, rue Victor-Hugo.","J'habite sur 12, rue Victor-Hugo."],"answer":"J'habite au 12, rue Victor-Hugo.","explain":"门牌号前的 à + le 固定缩合为 au：au 12, rue Victor-Hugo；单独 à 缺冠词，dans 和 sur 都不用于门牌号。","source":"写作自评 · A1 地址（production écrite A1）"},{"id":"q-writ-a1-0009","level":"A1","skill":"writing","prompt":"写作自评（谈爱好），选出正确的一句：","options":["J'aime beaucoup la musique française.","J'aime beaucoup de la musique française.","J'aime beaucoup la musique français.","J'aime beaucoup le musique française."],"answer":"J'aime beaucoup la musique française.","explain":"aimer + 定冠词表示泛指一类事物：la musique française；de la 是部分冠词误用，français 缺阴性配合（musique 阴性），musique 是阴性应用 la。","source":"写作自评 · A1 兴趣爱好（production écrite A1）"},{"id":"q-writ-a1-0010","level":"A1","skill":"writing","prompt":"写作自评（正式邮件开头），选出最得体的一句：","options":["Madame, Monsieur, je vous écris pour demander des informations.","Salut, je veux des informations.","Madame, Monsieur, je t'écris pour demander des informations.","Madame, Monsieur, je vous écris pour demander information."],"answer":"Madame, Monsieur, je vous écris pour demander des informations.","explain":"正式邮件用 Madame, Monsieur 配 vous；Salut 过于随便，vous 与 t' 人称冲突，demander information 缺不定冠词 des informations。","source":"写作自评 · A1 正式邮件（production écrite A1）"},{"id":"q-writ-a1-0011","level":"A1","skill":"writing","prompt":"写作自评（道歉），选出正确的一句：","options":["Je suis désolé de ne pas avoir répondu plus tôt.","Je suis désolé de ne pas répondre plus tôt.","Je suis désolé ne pas avoir répondu plus tôt.","Je suis désolé de pas avoir répondu plus tôt."],"answer":"Je suis désolé de ne pas avoir répondu plus tôt.","explain":"不定式的否定把 ne pas 一起放在不定式前：de ne pas avoir répondu；ne pas 分开写或漏掉介词 de 都不成立。","source":"写作自评 · A1 道歉短信（production écrite A1）"},{"id":"q-writ-a1-0012","level":"A1","skill":"writing","prompt":"写作自评（表达愿望），选出正确的一句：","options":["J'aimerais visiter Paris un jour.","J'aimerais que visiter Paris un jour.","J'aimerais de visiter Paris un jour.","J'aime visiterais Paris un jour."],"answer":"J'aimerais visiter Paris un jour.","explain":"条件式 j'aimerais + 不定式表委婉愿望；que 后面必须是从句，de + 不定式是错误搭配，第四个选项把两个变位形式叠用。","source":"写作自评 · A1 愿望（production écrite A1）"},{"id":"q-writ-a1-0013","level":"A1","skill":"writing","prompt":"写作自评（描写住处），选出正确的一句：","options":["Mon appartement est petit mais très lumineux.","Mon appartement est petit mais très lumineuse.","Mon appartement est petite mais très lumineux.","Mon appartement est petite mais très lumineuse."],"answer":"Mon appartement est petit mais très lumineux.","explain":"appartement 是阳性单数，表语 petit 不加 -e，lumineux 是阳性形式；petite 和 lumineuse 都是阴性形式，与名词性别不符。","source":"写作自评 · A1 居住（production écrite A1）"},{"id":"q-writ-a1-0014","level":"A1","skill":"writing","prompt":"写作自评（学习时长），选出正确的一句：","options":["J'apprends le français depuis deux ans.","J'apprends le français il y a deux ans.","J'apprends le français pendant deux ans.","J'apprends le français dans deux ans."],"answer":"J'apprends le français depuis deux ans.","explain":"从过去延续到现在用 depuis + 现在时；il y a 指过去的时点（且需过去时），pendant 表已结束的一段时间，dans 指将来的「……之后」。","source":"写作自评 · A1 学习情况（production écrite A1）"},{"id":"q-writ-a1-0015","level":"A1","skill":"writing","prompt":"写作自评（邀请），选出正确的一句：","options":["Je t'invite à dîner samedi soir chez moi.","Je t'invite à dîner samedi soir chez je.","Je t'invite de dîner samedi soir chez moi.","Je t'invite à dîner samedi soir chez mon."],"answer":"Je t'invite à dîner samedi soir chez moi.","explain":"inviter qqn à faire qch 用 à + 不定式，chez 后接重读代词 moi；de 受英语 invite to 影响是误搭，chez je / chez mon 都不是法语。","source":"写作自评 · A1 邀请（production écrite A1）"},{"id":"q-writ-a1-0016","level":"A1","skill":"writing","prompt":"写作自评（正式信函结束语），选出最规范的一句：","options":["Dans l'attente de votre réponse, je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées.","Dans l'attente de votre réponse, je vous prie d'agréer, Madame, Monsieur, mes salutations.","Dans l'attente de votre réponse, je vous prie agréer, Madame, Monsieur, mes salutations distinguées.","Dans l'attente votre réponse, je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées."],"answer":"Dans l'attente de votre réponse, je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées.","explain":"正式结束语固定用 je vous prie d'agréer… mes salutations distinguées；省掉 distinguées 不完整，漏 de（prie agréer）语法错误，attente 后必须有介词结构（dans l'attente de votre réponse）。","source":"写作自评 · A1 正式信函（production écrite A1）"}],"speaking":[{"id":"q-speak-a1-0001","level":"A1","skill":"speaking","prompt":"口语自评（向陌生人问路），选出最得体的一句：","options":["Excusez-moi, où est la gare, s'il vous plaît ?","Excuse-moi, où est la gare, s'il te plaît ?","Où gare ?","Donne-moi la gare."],"answer":"Excusez-moi, où est la gare, s'il vous plaît ?","explain":"对陌生人要用 vous 和 Excusez-moi… s'il vous plaît；tu 形式对陌生人不礼貌，第三句缺动词，命令式 Donne-moi 也失礼。自评标准：tu/vous 是否与关系匹配。","source":"口语自评 · A1 问路（production orale A1）"},{"id":"q-speak-a1-0002","level":"A1","skill":"speaking","prompt":"口语自评（自我介绍），选出最得体的一句：","options":["Bonjour, je m'appelle Wang Lei, enchanté(e).","Bonjour, je suis nom Wang Lei.","Bonjour, mon nom est appeler Wang Lei.","Bonjour, je m'appelle de Wang Lei."],"answer":"Bonjour, je m'appelle Wang Lei, enchanté(e).","explain":"s'appeler 是「叫……名字」的固定说法；je suis nom 是英语式直译，mon nom est appeler 结构混乱，s'appeler 后不用 de。","source":"口语自评 · A1 自我介绍（production orale A1）"},{"id":"q-speak-a1-0003","level":"A1","skill":"speaking","prompt":"口语自评（在咖啡馆点单），选出最得体的一句：","options":["Je voudrais un café, s'il vous plaît.","Je veux un café.","Donne-moi un café.","Je veux un café, s'il te plaît."],"answer":"Je voudrais un café, s'il vous plaît.","explain":"条件式 je voudrais 表礼貌；je veux 在服务场合生硬，命令式 Donne-moi 更失礼，s'il te plaît 与对店员应当使用的 vous 不搭配。","source":"口语自评 · A1 点餐（production orale A1）"},{"id":"q-speak-a1-0004","level":"A1","skill":"speaking","prompt":"口语自评（道歉），选出正确的一句：","options":["Je suis vraiment désolé, je ne l'ai pas fait exprès.","Je suis vraiment désolé, je ne l'ai pas fait par exprès.","Je suis vraiment désolé, je ne l'ai fait pas exprès.","Je suis vraiment désolé, je pas l'ai fait exprès."],"answer":"Je suis vraiment désolé, je ne l'ai pas fait exprès.","explain":"faire exprès（故意）是固定搭配，不加 par；否定时 ne…pas 要夹住助动词（ne l'ai pas fait），另外两种语序都不合法。","source":"口语自评 · A1 道歉（production orale A1）"},{"id":"q-speak-a1-0005","level":"A1","skill":"speaking","prompt":"口语自评（打电话），选出最得体的一句：","options":["Allô, bonjour, je voudrais parler à M. Dupont, s'il vous plaît.","Allô, je veux M. Dupont.","Allô, donne-moi M. Dupont.","Allô, je parle M. Dupont."],"answer":"Allô, bonjour, je voudrais parler à M. Dupont, s'il vous plaît.","explain":"电话请求用条件式 je voudrais parler à qqn；je veux 过于直接，命令式失礼，parler à 的介词 à 不能省略（否则变成「我说杜邦先生」）。","source":"口语自评 · A1 电话（production orale A1）"},{"id":"q-speak-a1-0006","level":"A1","skill":"speaking","prompt":"口语自评（请对方重复），选出最得体的一句：","options":["Pardon, pouvez-vous répéter, s'il vous plaît ?","Pardon, pouvez-vous répétez, s'il vous plaît ?","Pardon, pouvez-vous que répéter, s'il vous plaît ?","Pardon, répétez encore une fois !"],"answer":"Pardon, pouvez-vous répéter, s'il vous plaît ?","explain":"pouvoir 后接不定式 répéter；répétez 是变位形式，que 与不定式叠用错误，命令式 Répétez ! 对不熟的人显得生硬。","source":"口语自评 · A1 沟通策略（production orale A1）"},{"id":"q-speak-a1-0007","level":"A1","skill":"speaking","prompt":"口语自评（告别），选出正确的一句：","options":["Bonne journée, à demain !","Bon journée, à demain !","Bonne journée, à hier !","Bonne journée, au demain !"],"answer":"Bonne journée, à demain !","explain":"journée 是阴性名词，形容词用 bonne；à hier 表示「昨天见」不合逻辑，au demain 不是法语形式（应 à demain）。","source":"口语自评 · A1 告别（production orale A1）"},{"id":"q-speak-a1-0008","level":"A1","skill":"speaking","prompt":"口语自评（在商店说明来意），选出正确的一句：","options":["Bonjour, je cherche un cadeau pour ma mère.","Bonjour, je cherche un cadeau à ma mère.","Bonjour, je cherche pour ma mère un cadeau de.","Bonjour, je cherche un cadeau de ma mère."],"answer":"Bonjour, je cherche un cadeau pour ma mère.","explain":"chercher qch pour qqn 用 pour；à 是误搭，第三句语序与结构错乱，第四句 de ma mère 会变成「属于我妈妈的礼物」。","source":"口语自评 · A1 购物（production orale A1）"},{"id":"q-speak-a1-0009","level":"A1","skill":"speaking","prompt":"口语自评（问时间），选出正确的一句：","options":["Excusez-moi, quelle heure est-il ?","Excusez-moi, quelle heure il est ?","Excusez-moi, qu'elle heure est-il ?","Excusez-moi, quelle heure est-ce ?"],"answer":"Excusez-moi, quelle heure est-il ?","explain":"直接疑问用倒装 quelle heure est-il；第二句缺倒装，qu'elle（＝que elle）是拼写混淆，est-ce 后必须接完整结构（est-ce que…）。","source":"口语自评 · A1 问时间（production orale A1）"},{"id":"q-speak-a1-0010","level":"A1","skill":"speaking","prompt":"口语自评（寒暄天气），选出正确的一句：","options":["Il fait beau aujourd'hui, n'est-ce pas ?","Il fait beau aujourd'hui, n'est pas ?","Il fait beau aujourd'hui, c'est pas ?","Il fait beau aujourd'hui, non pas ?"],"answer":"Il fait beau aujourd'hui, n'est-ce pas ?","explain":"反意疑问的固定形式是 n'est-ce pas；漏掉 ce、写成 c'est pas（口语且结构混乱）、用 non pas（意思是「而不是」）都不正确。","source":"口语自评 · A1 寒暄（production orale A1）"},{"id":"q-speak-a1-0011","level":"A1","skill":"speaking","prompt":"口语自评（找洗手间），选出正确的一句：","options":["Où sont les toilettes, s'il vous plaît ?","Où est les toilettes, s'il vous plaît ?","Où sont toilettes, s'il vous plaît ?","Où les toilettes sont ?"],"answer":"Où sont les toilettes, s'il vous plaît ?","explain":"toilettes 是复数，动词用 sont 且必须带定冠词 les；主谓不一致、缺冠词、语序错误都不成立。","source":"口语自评 · A1 求助（production orale A1）"},{"id":"q-speak-a1-0012","level":"A1","skill":"speaking","prompt":"口语自评（谈工作），选出正确的一句：","options":["Je travaille dans une banque.","Je travaille à une banque.","Je travaille dans banque.","Je travaille sur une banque."],"answer":"Je travaille dans une banque.","explain":"在某个机构/场所内部工作用 dans；à 用于公司名或城市等具体点，sur 表「在……上面/关于」，且名词前必须有冠词。","source":"口语自评 · A1 工作（production orale A1）"},{"id":"q-speak-a1-0013","level":"A1","skill":"speaking","prompt":"口语自评（请对方说慢一点），选出最得体的一句：","options":["Désolé, je ne comprends pas. Pouvez-vous parler plus lentement ?","Désolé, je ne comprends pas. Pouvez-vous parler plus lent ?","Désolé, je comprends pas. Pouvez-vous parler plus lentement ?","Désolé, je ne comprends pas. Vous parlez plus lentement ?"],"answer":"Désolé, je ne comprends pas. Pouvez-vous parler plus lentement ?","explain":"修饰动词 parler 要用副词 lentement（lent 是形容词）；口语中省略 ne（je comprends pas）在礼貌场合应避免；陈述语序的疑问句不能表达正式请求。","source":"口语自评 · A1 沟通策略（production orale A1）"},{"id":"q-speak-a1-0014","level":"A1","skill":"speaking","prompt":"口语自评（接受邀请），选出正确的一句：","options":["Avec plaisir, merci beaucoup !","Avec le plaisir, merci beaucoup !","De plaisir, merci beaucoup !","Pour plaisir, merci beaucoup !"],"answer":"Avec plaisir, merci beaucoup !","explain":"avec plaisir 是无冠词的固定表达；加定冠词、换成 de 或 pour 都不是法语搭配。","source":"口语自评 · A1 回应邀请（production orale A1）"},{"id":"q-speak-a1-0015","level":"A1","skill":"speaking","prompt":"口语自评（电话留言），选出正确的一句：","options":["Bonjour, est-ce que je peux laisser un message, s'il vous plaît ?","Bonjour, est-ce que je peux laisser un message, s'il te plaît ?","Bonjour, est-ce que je peux laisse un message ?","Bonjour, est-ce que je peux que laisser un message ?"],"answer":"Bonjour, est-ce que je peux laisser un message, s'il vous plaît ?","explain":"pouvoir 后接不定式 laisser；s'il te plaît 与正式电话场合不符，laisse 是变位形式，que 与不定式不能叠用。","source":"口语自评 · A1 电话留言（production orale A1）"},{"id":"q-speak-a1-0016","level":"A1","skill":"speaking","prompt":"口语自评（结账），选出正确的一句：","options":["L'addition, s'il vous plaît.","Le addition, s'il vous plaît.","L'addition, s'il te plaît.","La addition, s'il vous plaît."],"answer":"L'addition, s'il vous plaît.","explain":"addition 是阴性单数且以元音开头，冠词一律省音为 l'（le/la 都要变 l'）；s'il te plaît 对服务员不够礼貌。","source":"口语自评 · A1 餐厅（production orale A1）"}]}}.A1;
